questionvariables.text:
/*STA 141 week2 quizes*/
correct_answer:rand_selection([
[1, true, "Discrete and continuous"],
[2, true, "Qualitative and Quantitative"]
], 1);
incorrect_answers:rand_selection([
[3, false, "Population and sample"],
[4, false, "Ratio and Interval"],
[5, false, "Nominal and ordinal"],
[6, false, "Descriptive and Inferential"],
[7, false, "Probabilistic and non-probabilistic"],
[8, false, "Quota and cluster"]
], 3);
ta: random_permutation(append(correct_answer,incorrect_answers));

ta_index: sort(makelist(x[1], x, ta));
ta_largest: last(ta_index);
